   432	            /* Shouldn't happen - same as default case */
   433	            SSLfatal(s, SSL_AD_INTERNAL_ERROR,
   434	                     SSL_F_OSSL_STATEM_CLIENT13_WRITE_TRANSITION,
   435	                     ERR_R_INTERNAL_ERROR);
