   437	        }
   438	        st->hand_state = TLS_ST_OK;
   439	        return WRITE_TRAN_CONTINUE;
   440	
   441	    case TLS_ST_CR_FINISHED:
   442	        if (s->early_data_state == SSL_EARLY_DATA_WRITE_RETRY
   443	                || s->early_data_state == SSL_EARLY_DATA_FINISHED_WRITING)
