   485	            st->hand_state = TLS_ST_CW_KEY_UPDATE;
   486	            return WRITE_TRAN_CONTINUE;
   487	        }
   488	
   489	        /* Try to read from the server instead */
   490	        return WRITE_TRAN_FINISHED;
   491	    }
